using System.IO;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace CtrlZed;

// Original colour-picker image supplied by Martyn. The WPF crop removes only
// the screenshot's surrounding padding; the source pixels are retained intact.
internal static class TextColourIcon
{
    static readonly ImageSource source = Load();
    internal static ImageSource Create() => source;

    static ImageSource Load()
    {
        using var stream = new MemoryStream(Convert.FromBase64String(Data));
        var bitmap = new BitmapImage();
        bitmap.BeginInit();
        bitmap.CacheOption = BitmapCacheOption.OnLoad;
        bitmap.StreamSource = stream;
        bitmap.EndInit();
        bitmap.Freeze();
        var icon = new CroppedBitmap(bitmap, new Int32Rect(9, 7, 28, 28));
        icon.Freeze();
        return icon;
    }

    const string Data = "";
}
